def max_average_power(n, k, m, a):
    a.sort()
    prefix_sum = [0]
    for i in range(n):
        prefix_sum.append(prefix_sum[-1] + a[i])

    def possible(mid):
        left_remove = 0
        right_increase = []
        current_sum = prefix_sum[n]
        for i in range(n-1, -1, -1):
            if a[i] > mid:
                left_remove += 1
                current_sum -= a[i]
            else:
                break

        for i in range(left_remove, n):
            if a[i] < mid:
                need_increase = mid - a[i]
                if need_increase <= k:
                    right_increase.append(need_increase)
                elif need_increase > k:
                    return False

        total_operations = left_remove + sum(right_increase)
        return total_operations <= m

    low, high = min(a), max(a)
    while high - low > 1e-9:
        mid = (low + high) / 2
        if possible(mid):
            low = mid
        else:
            high = mid

    return low

